  for(const key of ['sheet','lightbox','onboarding']){equal(hardened[key].display,'none',`${label}: ltd-active fail-safe hides residual ${key}`);equal(hardened[key].pointerEvents,'none',`${label}: ltd-active fail-safe disables residual ${key} pointer input`);equal(hardened[key].width,0,`${label}: ltd-active fail-safe gives residual ${key} zero width`);equal(hardened[key].height,0,`${label}: ltd-active fail-safe gives residual ${key} zero height`);}equal(hardened.blockedOpenSheet,true,`${label}: personal openSheet is blocked while Ltd is active`);equal(hardened.noticeOpen,false,`${label}: blocked personal sheet does not retain open state`);
