async function backupAndPresentation(page){
  const backup=await page.evaluate(async()=>{const json=TaxMateState.createExport(S,{appVersion:TaxMateCore.VERSIONS.APP_VERSION,buildId:TaxMateCore.VERSIONS.BUILD_ID,deviceId:DEVICE_ID}),restored=TaxMateState.importBackup(json,Date.now(),'isolated-data-restore'),full=await buildPortableArchive(S),inspected=await TaxMatePortableBackup.inspectArchive(full.archive);return{jsonVersion:json.exportSchemaVersion,dataHash:JSON.stringify(TaxMateLtdSync.recordsForSync(restored)),sourceHash:JSON.stringify(TaxMateLtdSync.recordsForSync(S)),manifestEntries:full.manifest.length,manifestValidated:inspected.metadata.receiptCount===inspected.receipts.length,fullHash:JSON.stringify(TaxMateLtdSync.recordsForSync(inspected.state)),receiptCount:inspected.receipts.length};});equal(backup.dataHash,backup.sourceHash,'Data-only backup restores identical Ltd relationships in isolation');equal(backup.fullHash,backup.sourceHash,'Full Backup restores identical Ltd relationships in isolation');check(backup.manifestValidated,'Full Backup archive manifest validates exactly');
  for(const locale of ['en','zh-HK','pl','ro','es','ur']){await page.evaluate(locale=>{S.settings.lang=locale==='zh-HK'?'zh':locale;persistRemoteState();},locale);await windowOpen(page);const semantics=await page.locator('#taxmate-ltd-ui-root .tm-app').evaluate(node=>({lang:node.lang,dir:node.dir}));equal(semantics.lang,locale,`${locale} renders in the actual app`);equal(semantics.dir,locale==='ur'?'rtl':'ltr',`${locale} direction is correct in the actual app`);}
  await page.evaluate(()=>{S.settings.lang='en';S.settings.theme='dark';persistRemoteState();});await windowOpen(page);check((await page.locator('#taxmate-ltd-ui-root').evaluate(node=>getComputedStyle(node).display))!=='none','dark mode keeps the actual Ltd workspace visible');
  const mobileOverflow=await page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth);check(mobileOverflow,'390×844 actual app has no unexpected horizontal overflow');await page.screenshot({path:path.join(evidence,'actual-app-mobile-dark-en.png'),fullPage:true});await page.setViewportSize({width:1440,height:1000});await windowOpen(page);check(await page.getByRole('tab',{name:'Overview'}).count()===1,'desktop actual app renders the Company Workspace');check(await page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth),'desktop actual app has no unexpected horizontal overflow');await page.screenshot({path:path.join(evidence,'actual-app-desktop-dark-en.png'),fullPage:true});
}
async function windowOpen(page){await page.evaluate(()=>TaxMateLtdProductionAdapter.openExistingCompany());await page.waitForFunction(()=>TaxMateLtdUIFacade.getSnapshot().navigation.routes.at(-1).screenId.startsWith('ltd.'));}

async function exercisePersonalOverlayIsolation(page,legacyBusinessId){
  await page.evaluate(id=>openBiz(id),legacyBusinessId);await page.locator('#sb-biz.open').waitFor();
  const before=await page.evaluate(()=>({title:document.getElementById('bz-title').textContent,sheetOpen:document.body.classList.contains('sheet-open'),visible:getComputedStyle(document.getElementById('sb-biz')).display!=='none'}));equal(before.title,'Edit business','real legacy Edit business sheet is open before entering Ltd');equal(before.sheetOpen,true,'legacy Edit business sets personal sheet-open before Ltd transition');equal(before.visible,true,'legacy Edit business sheet is visibly rendered before Ltd transition');
  await page.locator('#bz-name').focus();await page.evaluate(()=>TaxMateLtdProductionAdapter.openExistingCompany());await page.waitForFunction(()=>document.body.classList.contains('ltd-active'));
  await assertLtdShell(page,'existing Ltd entered while legacy Edit business was open');
  await page.getByRole('tab',{name:'Money',exact:true}).click();await waitFor(()=>route(page).then(value=>value==='ltd.workspace.money'),'Ltd Money tab is immediately operable after stale personal sheet cleanup');check(true,'Ltd interaction is not intercepted by the former personal Edit business sheet');await page.getByRole('tab',{name:'Overview',exact:true}).click();await waitFor(()=>route(page).then(value=>value==='ltd.workspace.overview'),'Ltd Overview remains operable after stale personal sheet cleanup');
  const screenshotName='actual-app-personal-overlay-isolation.png';await page.screenshot({path:path.join(evidence,screenshotName),fullPage:true});visualEvidence.push({name:screenshotName,screen:'ltd.workspace.overview',sourceState:'legacy Edit business sheet was open',personalSheetVisible:false});
  await page.getByRole('button',{name:'All businesses'}).click();await assertPersonalShell(page,'All businesses after stale personal sheet cleanup');
}

